INSERT INTO public.ufte_task_types VALUES
	('ENB_FPGA_UPGRADE', 'enb_upgrade', '4G升级', '4G FPGA 升级', '复用 4G 侧 FPGA 升级任务链路，统一到 UFTE 任务中心。', 'DOWNLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_FILE_TRANSFER", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_ENB_UPGRADE_FPGA', '["4G eNB", "QAFA", "QAFB", "FPGA"]', 'Firmware Upgrade Fpga', 'Firmware Upgrade Fpga', true, 'firmware/{fpga_path}', '{fpga_name}', '{fpga_name}', 'firmware.fileSize', 'firmware.md5', 'false', 0, '/smallcell/FileDownloadService/firmware/fpga/{path}', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:47.906664+08', NULL, 100),
	('VERSION_ROLLBACK', 'version_rollback', '基站版本回退', '基站版本回退', '通过 TR069 SetParameterValues 触发设备回退到上一版本，不需要下载文件。', 'SET_PARAM_VALUES', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_REBOOT_COMPLETE"]', '', 'CODE_VERSION_ROLLBACK', '["4G eNB", "5G gNB", "QAFA", "QAFB", "BBU-XSS", "BBU-QSS"]', '', '版本回退', false, '', '', '', '', '', '', 0, '', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:47.906664+08', NULL, 100),
	('RUNTIME_LOG_COLLECT', 'station_log', '日志收集', '运行日志采集', '复用现网日志采集 Upload 链路，提供 UFTE 内置的运行日志收集模板。', 'UPLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "PRE_VALIDATE", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_RUNTIME_LOG_COLLECT', '["4G eNB", "5G gNB", "DXDF", "BBU-QSS"]', '6', '运行日志', true, '', 'runtime-{task_id8}-{sn}.tar.gz', 'runtime-{task_id8}-{sn}.tar.gz', '', '', '', 0, '/smallcell/FileUploadService?fileType={fileType}&filename={targetFileName}', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:47.906664+08', NULL, 100),
	('FAULT_LOG_COLLECT', 'station_log', '日志收集', '故障日志采集', '复用现网日志采集 Upload 链路，提供 UFTE 内置的故障日志收集模板。', 'UPLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "PRE_VALIDATE", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_FAULT_LOG_COLLECT', '["4G eNB", "5G gNB", "DXDF", "BBU-QSS"]', '8', '故障日志', true, '', 'fault-{task_id8}-{sn}.tar.gz', 'fault-{task_id8}-{sn}.tar.gz', '', '', '', 0, '/smallcell/FileUploadService?fileType={fileType}&filename={targetFileName}', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:47.906664+08', NULL, 100),
	('ENB_IMG_UPGRADE', 'enb_upgrade', '4G升级', '4G 基站软件升级', '复用现网软件升级链路，统一承载 4G 基站镜像升级任务。', 'DOWNLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_FILE_TRANSFER", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_ENB_UPGRADE_IMAGE', '["4G eNB", "QAFA", "QAFB"]', '1 Firmware Upgrade Image', '1 Firmware Upgrade Image', true, 'firmware/{minio_path}', '{firmware_name}', '{firmware_name}', 'firmware.fileSize', 'firmware.md5', 'false', 0, '/smallcell/FileDownloadService/firmware/img/{path}', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:47.906664+08', NULL, 100),
	('ENB_PATCH_UPGRADE', 'enb_upgrade', '4G升级', '4G Patch 增量升级', '复用软件管理补丁升级任务链路，统一收口到 UFTE 任务入口。', 'DOWNLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_FILE_TRANSFER", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_ENB_UPGRADE_PATCH', '["4G eNB", "QAFA", "QAFB", "PATCH"]', 'X {OUI} Software Upgrade Patch', 'X {OUI} Software Upgrade Patch', true, 'firmware/{patch_path}', '{patch_name}', '{patch_name}', 'firmware.fileSize', 'firmware.md5', 'true', 0, '/smallcell/FileDownloadService/firmware/patch/{path}', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:47.906664+08', NULL, 100),
	('GNB_IMG_UPGRADE', 'gnb_upgrade', '5G升级', '5G 基站软件升级', '复用现网 5G 升级调测通过的下载与升级完成事件链路。', 'DOWNLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_FILE_TRANSFER", "WAIT_TRANSFER_COMPLETE", "WAIT_INFORM_EVENT"]', '102 UPGRADE FINISH', 'CODE_GNB_UPGRADE_IMAGE', '["5G gNB", "BBU-XSS", "BBU-QSS"]', '1 Firmware Upgrade Image', '1 Firmware Upgrade Image', true, 'firmware/{minio_path}', '{firmware_name}', '{firmware_name}', 'firmware.fileSize', 'firmware.md5', 'false', 0, '/smallcell/FileDownloadService/firmware/img/{path}', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:47.906664+08', NULL, 100),
	('CONFIG_BACKUP_XML', 'config_backup', '配置文件备份', '配置文件备份（XML）', '标准平台（BLQ/QLS 等）配置文件备份，TR-069 Upload FileType=10 {OUI} Configuration File。', 'UPLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "PRE_VALIDATE", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_CONFIG_BACKUP', '["4G eNB", "5G gNB", "QAFA", "QAFB", "BBU-XSS", "BBU-QSS"]', '10 {OUI} Configuration File', '10 {OUI} Configuration File', false, '', 'backup-{task_id8}-{sn}.xml', 'backup-{task_id8}-{sn}.xml', '', '', '', 0, '/smallcell/FileUploadService?fileType=CONFIGBACKUP_XML&sn={sn}&taskId={taskId}&filename={targetFileName}', 'system', '2026-05-31 11:28:48.208523+08', '2026-05-31 11:28:48.208523+08', NULL, 100),
	('CONFIG_RESTORE', 'config_restore', '配置文件恢复', '配置文件恢复', '复用现网配置恢复 Download 链路，提供 UFTE 内置的配置文件恢复模板。', 'DOWNLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "PRE_VALIDATE", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_CONFIG_RESTORE', '["4G eNB", "5G gNB", "QAFA", "QAFB", "BBU-XSS", "BBU-QSS"]', '10 <OUI> Configuration File', '10 <OUI> Configuration File', false, 'config_backup/{object_path}', '{file_name}', '{file_name}', '', '', '', 0, '/smallcell/FileDownloadService/config_backup/{object_path}', 'system', '2026-05-31 11:28:47.906664+08', '2026-05-31 11:28:48.859473+08', NULL, 100),
	('CONFIG_BACKUP_NV', 'config_backup', '配置文件备份', '配置文件备份（NV）', 'NV 平台（MLQ/MLN_SC 等）配置文件备份，TR-069 Upload FileType=12 {OUI} Configuration File。', 'UPLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "PRE_VALIDATE", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_CONFIG_BACKUP', '["MLQ", "MLN_SC"]', '12 {OUI} Configuration File', '12 {OUI} Configuration File', false, '', 'backup-{task_id8}-{sn}.nv', 'backup-{task_id8}-{sn}.nv', '', '', '', 0, '/smallcell/FileUploadService?fileType=CONFIGBACKUP_NV&sn={sn}&taskId={taskId}&filename={targetFileName}', 'system', '2026-05-31 11:28:48.208523+08', '2026-05-31 11:28:48.208523+08', NULL, 100),
	('LICENSE_UPGRADE', 'license_upgrade', '设备License升级', '设备License升级', '从 license 库取目标设备的最新一份 license 文件，通过 TR-069 Download RPC 下发到设备。', 'DOWNLOAD', true, true, '["CHECK_PERMISSION", "CHECK_ONLINE", "CHECK_CONFLICT", "PRE_VALIDATE", "SEND_RPC", "WAIT_RPC_RESPONSE", "WAIT_TRANSFER_COMPLETE"]', '', 'CODE_LICENSE_UPGRADE', '["4G eNB", "5G gNB", "QAFA", "QAFB", "BBU-XSS", "BBU-QSS"]', 'License File', 'License File', false, 'device-licenses/{object_path}', '{file_name}', '{file_name}', '', '', '', 0, '/smallcell/FileDownloadService/device-licenses/{object_path}', 'system', '2026-05-31 11:28:48.860497+08', '2026-05-31 11:28:48.860497+08', NULL, 100);
